import os,json,subprocess
from pathlib import Path
alias=Path('/srv/pink-iptv')
canonical=Path('/srv/projects/pink-iptv')
services=('ssh','nginx','postgresql@16-main','pink-iptv-backend','pink-vpn','fadego-staging','lowcost-europa','pm2-iptvpn-bot','pm2-telegram-robot-leads')
r={'action':'remove_legacy_pink_alias','removed':False}
def active():return {s:subprocess.run(['systemctl','is-active',s],capture_output=True,text=True,timeout=8).stdout.strip() for s in services}
try:
 assert os.geteuid()==0,'root needed'
 assert alias.is_symlink() and alias.resolve()==canonical and canonical.is_dir(),'not the expected alias'
 service=subprocess.run(['systemctl','cat','pink-iptv-backend'],capture_output=True,text=True,timeout=12)
 assert service.returncode==0
 assert '/srv/projects/pink-iptv/backend' in service.stdout and '/srv/pink-iptv' not in service.stdout,'backend has legacy path'
 before=active();assert all(v=='active' for v in before.values()),'critical service not active before'
 uses=[]
 for base in ('/etc/systemd/system','/etc/nginx','/usr/local/bin','/usr/local/sbin'):
  d=Path(base)
  if not d.is_dir():continue
  for c,ds,fs in os.walk(d):
   if len(Path(c).relative_to(d).parts)>3:ds[:]=[];continue
   for file in fs:
    p=Path(c)/file
    try:
     if p.is_file() and p.stat().st_size<300000 and '/srv/pink-iptv' in p.read_text(errors='ignore'):
      uses.append(str(p))
    except Exception:pass
 assert not uses,'active configuration still references alias'
 for p in Path('/proc').iterdir():
  if not p.name.isdigit():continue
  for part in ('cwd','exe'):
   try:
    target=os.readlink(p/part)
    assert not (target=='/srv/pink-iptv' or target.startswith('/srv/pink-iptv/')),'live process legacy path'
   except OSError:pass
 alias.unlink()
 r['removed']=True
 after=active()
 if not all(v=='active' for v in after.values()):
  alias.symlink_to(canonical)
  r.update({'removed':False,'rollback':True,'reason':'services changed'})
 else:
  r.update({'status':'REMOVED_VERIFIED','services_active':9,'legacy_alias_absent':not alias.exists() and not alias.is_symlink()})
except Exception as e:
 r.update({'status':'BLOCKED','reason':type(e).__name__+': '+str(e)[:220]})
print(json.dumps(r,separators=(',',':')))
